-- Article demandé par Tom le 06/11/2026 : avant-papier liste Zidane (Italie, Turquie). FR + EN.
INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured", "en_title", "en_dek", "en_body_html", "en_published")
SELECT 'Liste de Zidane : blessés, retours, surprises possibles… ce qu''il faut savoir avant l''annonce', 'liste-de-zidane-ce-qu-il-faut-savoir-et-les-surprises-possibles', 'Zinédine Zidane dévoile ce vendredi 6 novembre à 18h sa deuxième liste de sélectionneur, pour Italie-France et France-Turquie. Dembélé et Olise incertains, Tchouaméni et Zaïre-Emery annoncés de retour, Thauvin en embuscade : Passe D fait le point.', '<p><em>Article publié avant l''annonce officielle. Les noms évoqués ci-dessous sont des pistes rapportées par la presse, pas la liste. Passe D mettra l''article à jour dès 18h.</em></p><p>C''est le grand rendez-vous de la journée. Ce <strong>vendredi 6 novembre à 18h</strong>, au siège de la FFF, <strong>Zinédine Zidane</strong> annonce sa deuxième liste à la tête des Bleus. Elle concerne les deux derniers matchs de la phase de groupes de la Ligue des nations. Le sélectionneur peut appeler jusqu''à 26 joueurs, attendus à Clairefontaine dès lundi.</p><h2>Le programme</h2><ul><li><strong>Jeudi 12 novembre, 20h45</strong> : Italie – France, à Milan</li><li><strong>Dimanche 15 novembre, 20h45</strong> : France – Turquie, à Bordeaux (TF1)</li></ul><h2>Où en sont les Bleus ?</h2><p>Le début de l''ère Zidane est solide. En quatre matchs, la France a battu la Turquie (1-0), la Belgique (1-0 puis 4-1) et concédé le nul face à l''Italie (1-1). Avec 10 points, les Bleus sont en tête du groupe, devant l''Italie (7 points) et la Belgique (6 points). Le déplacement à Milan peut donc décider de la première place.</p><p>Pour sa première liste, en septembre, Zidane avait appelé 23 joueurs, avec cinq nouveaux : Guillaume Restes (Toulouse), Jérémy Jacquet (Liverpool), Andy Diouf (Inter), Lucas Da Cunha (Côme) et Estéban Lepaul (Rennes).</p><h2>L''infirmerie déborde</h2><p>C''est le casse-tête de Zidane. Selon la presse, plusieurs cadres sont touchés :</p><ul><li><strong>Ousmane Dembélé</strong> (cuisse) : très incertain, voire forfait</li><li><strong>Michael Olise</strong> : blessé contre Dortmund le 31 octobre, incertain</li><li><strong>Jules Koundé</strong> (cheville) : incertain</li><li><strong>William Saliba</strong>, <strong>Manu Koné</strong> (ischio-jambiers) et <strong>Estéban Lepaul</strong> (cheville) : forfaits probables</li><li><strong>Maxence Lacroix</strong> : forfait</li></ul><p>Sans Dembélé ni Olise, l''attaque perdrait deux de ses meilleures armes. Mbappé, Doué et Barcola devraient porter l''animation offensive.</p><h2>Les retours annoncés</h2><p><strong>Aurélien Tchouaméni</strong> devrait retrouver sa place. En septembre, Zidane l''avait laissé de côté, faute de rythme. <strong>Warren Zaïre-Emery</strong>, forfait lors du dernier rassemblement, serait lui aussi appelé selon TF1. Dans les buts, <strong>Robin Risser</strong> (Lens), qui avait déclaré forfait au dernier moment, est attendu.</p><h2>Les surprises possibles</h2><p>Voici les noms qui circulent. Rien n''est officiel.</p><ul><li><strong>Florian Thauvin (Lens)</strong> : à 33 ans, il réalise un début de saison superbe (4 buts et 8 passes décisives selon MadeInLensois, meilleur passeur de Ligue 1). Il a dit publiquement qu''il rêvait d''un retour. Ce serait la grosse surprise.</li><li><strong>Marcus Thuram (Inter)</strong> : candidat naturel pour compenser l''absence probable de Dembélé.</li><li><strong>Lucas Hernandez (PSG)</strong> : polyvalent, il peut dépanner dans l''axe comme à gauche, utile avec autant de blessés derrière.</li><li><strong>Wesley Fofana (Chelsea)</strong> : plus appelé depuis juin 2023, son nom revient avec les forfaits en défense centrale.</li><li><strong>Leny Yoro</strong> : convaincant contre la Belgique, il pourrait profiter de l''absence de Saliba.</li><li><strong>Maghnes Akliouche (PSG)</strong> : en concurrence avec Zaïre-Emery pour une place au milieu.</li><li><strong>Eli Junior Kroupi</strong> : revenu de blessure, une option offensive de plus.</li><li><strong>Pierre Kalulu</strong> : une piste au poste de latéral droit si Koundé ne peut pas tenir sa place.</li></ul><h2>La base attendue</h2><p>Autour de ces incertitudes, l''ossature devrait rester la même : Mbappé, Doué et Barcola devant ; Cherki, Camavinga et Da Cunha au milieu ; Upamecano, Konaté et Jacquet en défense centrale ; Truffert à gauche.</p><h2>Notre avis</h2><p>Avec autant d''absents, Zidane va devoir ouvrir la porte. Le retour de Tchouaméni semble logique, et la question Thauvin est la plus intéressante : récompenser la forme du moment, ou rester sur la jeunesse ? Réponse à 18h. Passe D vous donnera la liste complète et vos réactions sont les bienvenues. ⚽🇫🇷</p><h2>Sources</h2><p><a href="https://www.fff.fr/article/17631-la-liste-de-zinedine-zidane-le-6-novembre.html" target="_blank" rel="noopener noreferrer">FFF</a>, <a href="https://www.ouest-france.fr/sport/football/equipe-de-france/date-matches-joueurs-tout-savoir-sur-la-deuxieme-liste-de-zinedine-zidane-a-la-tete-de-lequipe-de-france-d3f36c54-d612-11f1-84f3-5611f158a658" target="_blank" rel="noopener noreferrer">Ouest-France</a>, <a href="https://www.tf1info.fr/sport/equipe-de-france-la-date-de-la-prochaine-liste-des-bleus-de-zinedine-zidane-pour-les-matchs-contre-l-italie-et-la-turquie-devoilee-2471459.html" target="_blank" rel="noopener noreferrer">TF1info</a>, <a href="https://rmcsport.bfmtv.com/football/equipe-de-france/equipe-de-france-la-prochaine-liste-de-zidane-devoilee-le-6-novembre_AV-202610220657.html" target="_blank" rel="noopener noreferrer">RMC Sport</a>, <a href="https://www.topmercato.com/2153170-equipe-de-france-une-place-pour-lucas-hernandez-et-tchouameni-fais-ta-liste-de-zidane/" target="_blank" rel="noopener noreferrer">TopMercato</a> et <a href="https://madeinlensois.ouest-france.fr/infos/article-equipe-de-france-florian-thauvin-pourrait-etre-l-une-des-surprises-de-la-prochaine-liste-de-zidane-544245.html" target="_blank" rel="noopener noreferrer">MadeInLensois</a>.</p><p>— Passe D</p>', 'article', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'actualites'),
